#!/usr/bin/env python3
# Some portions generated by Codex. Lossless exact-byte line interning; raw originals remain local.
import pathlib,json,hashlib,re
p=pathlib.Path(__file__).resolve().parent;lines=[];index={};files={}
for f in sorted((p/'runs').rglob('*')):
 if not f.is_file() or 'appdata' in f.relative_to(p/'runs').parts or f.name in ['full-stacks.json','profile.jfr']:continue
 raw=f.read_bytes();text=raw.decode('utf-8');ids=[]
 if f.name.startswith('query-') and f.suffix=='.log' and f.with_suffix('.json').exists():
  source=f.with_suffix('.json');original=source.read_text()
  compact=re.sub(r'"(?:\\.|[^"\\])*"|\s+',lambda m:m.group(0) if m.group(0).startswith('"') else '',original)+'\n'
  if compact.encode()==raw:
   files[str(f.relative_to(p))]={'compactJsonFrom':str(source.relative_to(p)),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
   continue
 for line in text.splitlines(keepends=True):
  if line not in index:index[line]=len(lines);lines.append(line)
  ids.append(index[line])
 reconstructed=''.join(lines[i] for i in ids).encode('utf-8');assert reconstructed==raw
 files[str(f.relative_to(p))]={'lines':ids,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
a={'format':'UTF-8 exact line interning v1','reconstruction':'Concatenate pool entries indexed by each file lines array; UTF-8 encode. SHA256 must match. No omitted textual request/log observations. JFR and giant raw export remain local.','pool':lines,'files':files}
(p/'run-evidence.json').write_text(json.dumps(a,separators=(',',':'))+'\n')
# Verify after actual serialization too.
b=json.loads((p/'run-evidence.json').read_text())
for name,v in b['files'].items():
 if 'compactJsonFrom' in v:
  ref=b['files'][v['compactJsonFrom']];original=''.join(b['pool'][i] for i in ref['lines']);raw=(re.sub(r'"(?:\\.|[^"\\])*"|\s+',lambda m:m.group(0) if m.group(0).startswith('"') else '',original)+'\n').encode()
 else:raw=''.join(b['pool'][i] for i in v['lines']).encode()
 assert hashlib.sha256(raw).hexdigest()==v['sha256'];assert raw==(p/name).read_bytes()
(p/'evidence-verification.json').write_text(json.dumps({'files':len(files),'rawBytes':sum(v['bytes'] for v in files.values()),'archiveBytes':(p/'run-evidence.json').stat().st_size,'allExactByteRoundTripsPassed':True},indent=2)+'\n')
# Publish bounded JSON chunks, retaining the monolithic verified archive locally.
chunks=[];batch=[];size=0;root=p/'evidence';root.mkdir(exist_ok=True)
for line in b['pool']:
 n=len(json.dumps(line).encode())
 if batch and size+n>600000:
  name=f'pool-{len(chunks):03d}.json';(root/name).write_text(json.dumps(batch,separators=(',',':'))+'\n');chunks.append(name);batch=[];size=0
 batch.append(line);size+=n
if batch:
 name=f'pool-{len(chunks):03d}.json';(root/name).write_text(json.dumps(batch,separators=(',',':'))+'\n');chunks.append(name)
b.pop('pool');b['poolChunks']=chunks
(root/'index.json').write_text(json.dumps(b,separators=(',',':'))+'\n')
assert [line for name in chunks for line in json.loads((root/name).read_text())]==a['pool']
